diff --git a/src/timer.sv b/src/timer.sv
index 1a3a4f1..5f7696d 100644
--- a/src/timer.sv
+++ b/src/timer.sv
@@ -55,11 +55,11 @@ module timer
         irq_o = 2'b0;

         // overlow irq
-        if (regs_q[`REG_TIMER] == 32'hffff_ffff)
+        if (regs_q[`REG_TIMER] == 32'hffff_ffff && prescaler_int == cycle_counter_q)
