     end
@@ -82,7 +82,7 @@ module timer
             regs_n[`REG_TIMER] = regs_q[`REG_TIMER] + 1;

         // reset prescaler cycle counter
-        if (cycle_counter_q >= regs_q[`REG_TIMER_CTRL])
